package com.networkmonitor.service;
import com.networkmonitor.dto.*;import com.networkmonitor.entity.*;import com.networkmonitor.exception.ResourceNotFoundException;import com.networkmonitor.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;import java.util.stream.Collectors;
@Service public class HistoryService{private final DeviceRepository devices;private final MonitoringMetricRepository metrics;public HistoryService(DeviceRepository d,MonitoringMetricRepository m){devices=d;metrics=m;}@Transactional(readOnly=true)public DeviceHistoryDto deviceHistory(Long id,int limit){Device d=devices.findById(id).orElseThrow(()->new ResourceNotFoundException("Device not found with id: "+id));List<MetricResponseDto> ms=metrics.findByDeviceIdOrderByTimestampDesc(id).stream().limit(limit).map(MetricResponseDto::fromEntity).collect(Collectors.toList());long reachable=ms.stream().filter(MetricResponseDto::isReachable).count();double avg=ms.stream().filter(x->x.getLatencyMs()!=null).mapToDouble(MetricResponseDto::getLatencyMs).average().orElse(0);DeviceHistoryDto r=new DeviceHistoryDto();r.setDeviceId(d.getId());r.setDeviceName(d.getName());r.setIpAddress(d.getIpAddress());r.setSampleCount(ms.size());r.setAvailabilityPercent(ms.isEmpty()?0:Math.round(reachable*10000.0/ms.size())/100.0);r.setAverageLatencyMs(Math.round(avg*100)/100.0);r.setMetrics(ms);r.setGeneratedAt(LocalDateTime.now());return r;}}
